select * from (values   ('random', 'medium', 'Nobody planned the queue. The bakery opens, the rain starts, and suddenly strangers are sharing one umbrella and the same furious opinion about a football match as if they had been waiting all week.', 40, 'fallback')) as v(category, difficulty, body, estimated_seconds, seed_tag)
